export function getLessonsForSchoolGrade(grade) {
  const g = String(grade || '').trim().toLowerCase();
  if (g.includes('1st') || g.includes('2nd') || g.includes('3rd') || g.includes('4th')) {
    return MASTER_LESSONS.filter(l => l.clusterId === 'std_1_4');
  }
  if (g.includes('5th') || g.includes('6th') || g.includes('7th') || g.includes('8th')) {
    return MASTER_LESSONS.filter(l => l.clusterId === 'std_5_8');
  }
  if (g.includes('9th') || g.includes('10th')) {
    return MASTER_LESSONS.filter(l => l.clusterId === 'std_9_10');
  }
  return MASTER_LESSONS.filter(l => l.clusterId === 'std_1_4');
}

export function getLessonsForAgeGroup(ageGroup) {
  const a = String(ageGroup || '').trim().toLowerCase();
  if (a.includes('kid') || a.includes('6-12') || a.includes('child')) {
    return MASTER_LESSONS.filter(l => l.clusterId === 'kids');
  }
  if (a.includes('teen') || a.includes('young') || a.includes('13-24') || a.includes('college')) {
    return MASTER_LESSONS.filter(l => l.clusterId === 'teens_young');
  }
  if (a.includes('pro') || a.includes('senior') || a.includes('adult') || a.includes('25+')) {
    return MASTER_LESSONS.filter(l => l.clusterId === 'professionals_seniors');
  }
  return MASTER_LESSONS.filter(l => l.clusterId === 'teens_young');
}

export function getCuratedLessons(accountType, grade, ageGroup) {
  if (accountType === 'STUDENT' || grade) {
    return getLessonsForSchoolGrade(grade);
  }
  return getLessonsForAgeGroup(ageGroup);
}

export function findCurriculumLesson(idOrTitle) {
  if (!idOrTitle) return null;
  const target = String(idOrTitle).trim().toLowerCase();
  return MASTER_LESSONS.find(l => 
    String(l.id) === target || 
    String(l.numericId) === target || 
    l.title.toLowerCase() === target
  ) || null;
}
